package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.content.JdbcContentReads;
import com.lianxibu.site.service.content.ContentReadService;
import org.junit.jupiter.api.Test;

/** A valid original paid-response-shaped fixture survives business rollback; no actual model call or application authority is implied. */
class CatalogAnalysisFailureRetentionTest {
    boolean mysql(){return false;}
    CatalogDayAnalysisResultTest helper(){return new CatalogDayAnalysisResultTest(){@Override boolean mysql(){return CatalogAnalysisFailureRetentionTest.this.mysql();}};}
    ResultJdbcStore store(CatalogDayAnalysisResultTest.Built built,boolean manual){var data=built.data().data().data().data();var f=data.f().f;return new ResultJdbcStore(f.source,built.identity(),new ContentReadService(new JdbcContentReads(f.source),f.tx,ContentReadService.denyUnverifiedReferences()),target->built.data().validity().exactVersionExists(target)&&built.data().validity().validity(target).effectiveValid(),built.data().clock(),"analysis-worker",manual);}
    @Test void NativeContentFailureRetainsCompleteOriginalValidatedResponseAndFirstWinsWithoutApplying(){var helper=helper();var built=helper.fixture("workflow",false);var data=built.data().data().data().data();var f=data.f().f;f.jdbc.execute("ALTER TABLE contents ADD CONSTRAINT fictional_analysis_retain_failure CHECK(input_job_id<>'"+built.identity().rootId()+"')");var expected=ResultApplicationService.validate(built.application().input(),built.raw());assertThrows(RuntimeException.class,()->helper.resultOf(built,"retention-failure"));var retained=data.outer().snapshot(data.f(),()->store(built,false).retained(built.identity().rootId()));assertEquals(expected,retained);assertEquals(expected.resultHash(),f.jdbc.queryForObject("SELECT LOWER(HEX(result_hash)) FROM jobs WHERE id=?",String.class,built.identity().rootId()));int jobs=f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);assertThrows(RuntimeException.class,()->helper.resultOf(built,"retention-failure"));assertEquals(jobs,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals("queued",f.jdbc.queryForObject("SELECT analysis_state FROM analyzed_entities",String.class));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM contents WHERE input_job_id=?",Integer.class,built.identity().rootId()));assertNull(f.jdbc.queryForObject("SELECT applied_at FROM jobs WHERE id=?",java.sql.Timestamp.class,built.identity().rootId()));assertEquals("occupied",f.jdbc.queryForObject("SELECT slot_state FROM worker_lock",String.class));assertEquals(1,f.jdbc.queryForObject("SELECT call_count FROM jobs WHERE id=?",Integer.class,built.identity().rootId()));assertEquals(2,f.sends);}
    @Test void ARefusalBeforeBusinessWriterStillRetainsOriginalValidResponseButNeverGrantsApplication(){var helper=helper();var built=helper.fixture("model",false);var data=built.data().data().data().data();var f=data.f().f;f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='source_day_dedup'",new byte[32]);assertThrows(RuntimeException.class,()->helper.resultOf(built,"broken-day-retention"));assertEquals(ResultApplicationService.validate(built.application().input(),built.raw()),data.outer().snapshot(data.f(),()->store(built,false).retained(built.identity().rootId())));assertEquals("queued",f.jdbc.queryForObject("SELECT analysis_state FROM analyzed_entities",String.class));assertNull(f.jdbc.queryForObject("SELECT applied_at FROM jobs WHERE id=?",java.sql.Timestamp.class,built.identity().rootId()));assertEquals(1,f.jdbc.queryForObject("SELECT call_count FROM jobs WHERE id=?",Integer.class,built.identity().rootId()));assertEquals(2,f.sends);}
    @Test void InvalidSemanticResponseAndDamagedOriginalInputCannotTriggerRetention(){var helper=helper();var built=helper.fixture("skill",false);var data=built.data().data().data().data();var f=data.f().f;assertThrows(RuntimeException.class,()->built.application().service().applyAutomatic(built.application().input(),"{}",helper.action(built,"invalid-envelope")));assertNull(f.jdbc.queryForObject("SELECT result_hash FROM jobs WHERE id=?",byte[].class,built.identity().rootId()));f.jdbc.update("UPDATE jobs SET payload_hash=? WHERE owner_job_id=? AND purpose='input'",new byte[32],built.identity().rootId());assertFalse(store(built,false).retainAfterAutomaticFailure(built.application().input()));assertThrows(RuntimeException.class,()->helper.resultOf(built,"invalid-input"));assertNull(f.jdbc.queryForObject("SELECT result_hash FROM jobs WHERE id=?",byte[].class,built.identity().rootId()));assertEquals(1,f.jdbc.queryForObject("SELECT call_count FROM jobs WHERE id=?",Integer.class,built.identity().rootId()));assertEquals(2,f.sends);}
    @Test void RetentionCapabilityIsAutomaticOnlyAndOriginalCompleteProfileIsRequired(){var built=helper().fixture("agent",true);assertTrue(store(built,false).retainAfterAutomaticFailure(built.application().input()));assertFalse(store(built,true).retainAfterAutomaticFailure(built.application().input()));assertFalse(store(built,false).retainAfterAutomaticFailure(null));var data=built.data().data().data().data();assertEquals(2,data.f().f.sends);assertNull(data.f().f.jdbc.queryForObject("SELECT result_hash FROM jobs WHERE id=?",byte[].class,built.identity().rootId()));}
}
